cd /tmp/sv-764a825988bd47878552f7df7f92019f && cat > ReadBinlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);

// Check all projects
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    var projErrors = p.FindChildrenRecursive<Error>();
    Console.WriteLine($"{p.Name} (Target: {p.TargetFramework}) - Errors: {projErrors.Count}");
    foreach (var e in projErrors)
        Console.WriteLine($"  error {e.Code}: {e.Text}");
}

// Check for MSB errors (cascading failures)
Console.WriteLine("\n=== Messages containing 'failed' ===");
var msgs = build.FindChildrenRecursive<Message>();
foreach (var m in msgs)
{
    if (m.Text != null && (m.Text.Contains("failed") || m.Text.Contains("error MSB")))
        Console.WriteLine($"  {m.Text}");
}
EOF
